def zigzag_convert(s, n):
    if n <= 1 or n >= len(s):
        return s
    rows = [''] * n
    cur, step = 0, 1
    for ch in s:
        rows[cur] += ch
        if cur == 0:
            step = 1
        elif cur == n - 1:
            step = -1
        cur += step
    return ''.join(rows)

