def three_sum_zero_triplets(xs):
    xs = sorted(xs)
    n = len(xs)
    res = set()
    for i in range(n - 2):
        if i > 0 and xs[i] == xs[i - 1]:
            continue
        lo, hi = i + 1, n - 1
        while lo < hi:
            s = xs[i] + xs[lo] + xs[hi]
            if s == 0:
                res.add((xs[i], xs[lo], xs[hi]))
                lo += 1
                hi -= 1
            elif s < 0:
                lo += 1
            else:
                hi -= 1
    return sorted(res)

