def first_unbalanced_bracket_index(s):
    opens = set('([{')
    closes = {')': '(', ']': '[', '}': '{'}
    stack = []
    for i, ch in enumerate(s):
        if ch in opens:
            stack.append((ch, i))
        elif ch in closes:
            if not stack or stack[-1][0] != closes[ch]:
                return i
            stack.pop()
    if stack:
        return stack[0][1]
    return -1

