def sliding_window_maximum(xs, k):
    n = len(xs)
    if n == 0 or k <= 0 or k > n:
        return []
    from collections import deque
    dq = deque()
    out = []
    for i, x in enumerate(xs):
        while dq and xs[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            out.append(xs[dq[0]])
    return out

