def vigenere_cipher_encode(s, key):
    if not key:
        return s
    out = []
    key = key.lower()
    ki = 0
    for ch in s:
        if ch.isalpha():
            shift = ord(key[ki % len(key)]) - ord('a')
            base = ord('A') if ch.isupper() else ord('a')
            out.append(chr((ord(ch) - base + shift) % 26 + base))
            ki += 1
        else:
            out.append(ch)
    return ''.join(out)

