def validate_iso_date_leapyear(s):
    parts = s.split('-')
    if len(parts) != 3:
        return False
    y_str, mo_str, d_str = parts
    if len(y_str) != 4 or len(mo_str) != 2 or len(d_str) != 2:
        return False
    if not (y_str.isdigit() and mo_str.isdigit() and d_str.isdigit()):
        return False
    year, month, day = int(y_str), int(mo_str), int(d_str)
    if month < 1 or month > 12:
        return False
    days_in_month = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month == 2 and (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)):
        max_day = 29
    else:
        max_day = days_in_month[month - 1]
    return 1 <= day <= max_day

