def kth_most_common_char(s, k):
    if not s or k < 1:
        return None
    counts = {}
    first_seen = {}
    for i, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        if ch not in first_seen:
            first_seen[ch] = i
    ordered = sorted(counts.keys(), key=lambda c: (-counts[c], first_seen[c]))
    if k > len(ordered):
        return None
    return ordered[k - 1]

