def interval_gaps_after_merge(intervals, lo, hi):
    if not intervals:
        merged = []
    else:
        s = sorted(intervals, key=lambda p: p[0])
        merged = [list(s[0])]
        for start, end in s[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
    out = []
    cur = lo
    for start, end in merged:
        if start > cur:
            out.append((cur, start))
        cur = max(cur, end)
    if cur < hi:
        out.append((cur, hi))
    return out

